35			// regardless of its value: even an integer part too long for int64
36			// (18446744073709551616 is 2^64) and an exponent whose value is below 1
37			// stay an integer-format rejection with the submitted text, never a
38			// range error or an accepted conversion.
39			{"18446744073709551616.0", 0, "expectedRevision must be an integer, got 18446744073709551616.0"},
40			{"18446744073709551616e-20", 0, "expectedRevision must be an integer, got 18446744073709551616e-20"},
41			{"-18446744073709551616e-20", 0, "expectedRevision must be an integer, got -18446744073709551616e-20"},
42			{"18446744073709551616E0", 0, "expectedRevision must be an integer, got 18446744073709551616E0"},
43			// Exponent notation that happens to equal an in-range integer is still
44			// the wrong notation; it must not parse to that integer.
45			{"9223372036854775807e0", 0, "expectedRevision must be an integer, got 9223372036854775807e0"},
46			// Pure integer notation above int64 keeps the range reason: the digits
47			// carry no decimal point or exponent, so the value is simply too large.
48			{"9223372036854775808", 0, "expectedRevision must be an integer between 0 and"},
49			{"-9223372036854775809", 0, "expectedRevision must be an integer between 0 and"},
50		}
51		for _, tc := range cases {
52			t.Run(tc.text, func(t *testing.T) {
53				got, err := ParseExpectedRevision(tc.text)
54				if tc.err == "" {
55					if err != nil {
56						t.Fatalf("unexpected error: %v", err)
57					}
58					if got != tc.want {
59						t.Fatalf("got %d want %d", got, tc.want)
