70	// revisionRangeBound is the accepted upper bound for the test build's
71	// architecture, mirroring maxRevision.
72	func revisionRangeBound() int64 {
73		if strconv.IntSize == 32 {
74			return math.MaxInt32
75		}
76		return math.MaxInt64
77	}
