79	// TestValidateExpectedRevisionRange checks the raw int64 value before it is
80	// narrowed to int. The decisive case only exists on a 32-bit build: values that
81	// fit int64 but wrap when converted to int (4294967297 -> 1) must be rejected.
82	// On a 64-bit build that value is a legitimate integer and proceeds to the
83	// ordinary revision comparison.
84	func TestValidateExpectedRevisionRange(t *testing.T) {
85		bound := revisionRangeBound()
86	
87		if err := validateExpectedRevision(0); err != nil {
88			t.Fatalf("0 should be valid: %v", err)
89		}
90		if err := validateExpectedRevision(bound); err != nil {
91			t.Fatalf("upper bound %d should be valid: %v", bound, err)
92		}
