19	// decodeRegisterOutput parses one register command output.
20	func decodeRegisterOutput(t *testing.T, out string) registerOutput {
21		t.Helper()
22		var got registerOutput
23		if err := json.Unmarshal([]byte(out), &got); err != nil {
24			t.Fatalf("output is not JSON: %v\n%s", err, out)
