51	// TestRegisterExpectedRevisionBeyondInt64 covers the word-size-independent
52	// overflow: an integer too large even for int64 is invalid for every request
53	// kind, with the range reason and the raw value, and never reported as a
54	// conflict or not_found.
55	func TestRegisterExpectedRevisionBeyondInt64(t *testing.T) {
56		input := `{"requests":[
57			{"type":"register","service":"svc","expectedRevision":` + hugeRevisionJSON + `,"instances":[{"id":"i1","address":"h1:8080"}]},
58			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
59			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":` + hugeRevisionJSON + `,"sequence":1,"healthy":true},
60			{"type":"select","service":"svc","expectedRevision":` + hugeRevisionJSON + `},
61			{"type":"select","service":"missing","expectedRevision":` + hugeRevisionJSON + `}
62		]}`
63		out, code := runRegisterWith(t, input)
