123				r := got.Results[0]
124				if r.OK || r.Error != "invalid" {
125					t.Fatalf("want invalid, got %+v", r)
126				}
127				if !strings.Contains(r.Reason, "expectedRevision must be an integer") ||
128					strings.Contains(r.Reason, "between 0 and") {
129					t.Fatalf("want the integer-type reason, got %q", r.Reason)
130				}
131			})
132		}
133		// Missing and explicit null keep the required message.
134		for name, input := range map[string]string{
135			"missing register": `{"requests":[{"service":"s","instances":[]}]}`,
136			"null register":    `{"requests":[{"service":"s","expectedRevision":null,"instances":[]}]}`,
137			"missing health":   `{"requests":[{"type":"health","service":"s","instanceId":"a","sequence":1,"healthy":true}]}`,
138			"missing select":   `{"requests":[{"type":"select","service":"s"}]}`,
139		} {
140			t.Run(name, func(t *testing.T) {
141				out, code := runRegisterWith(t, input)
142				if code != 1 {
143					t.Fatalf("exit code: %d", code)
144				}
145				r := decodeRegisterOutput(t, out).Results[0]
146				if r.OK || r.Error != "invalid" || !strings.Contains(r.Reason, "required") {
147					t.Fatalf("want the required-field reason, got %+v", r)
148				}
