208			{"type":"select","service":"svc","expectedRevision":` + wrapPositive + `,"sessionKey":"s"},
209			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},
210			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s"},
211			{"type":"select","service":"svc","expectedRevision":1}
