226		// never a conflict/not_found, carrying no target or comparison fields.
227		for i, submitted := range []string{wrapPositive, wrapNegative, wrapPositive, wrapPositive} {
228			r := got.Results[i+1]
229			assertRangeInvalid(t, r, 1, submitted)
230			if r.InstanceID != "" || r.Address != "" {
231				t.Fatalf("result %d must fabricate no target: %+v", i+1, r)
232			}
233		}
234		// 5: the rejected health wrote nothing; this valid report is the first
235		// observation and lands at sequence 1.
236		if r := got.Results[5]; !r.OK || !r.Changed || r.Sequence != 1 || r.Revision != 1 {
237			t.Fatalf("result 5 valid health: %+v", r)
238		}
239		// 6: the failed item 4 never bound "s", so this first success rotates to the
240		// smallest healthy id (i1) and binds now.
241		if r := got.Results[6]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 1 {
242			t.Fatalf("result 6 first session select: %+v", r)
243		}
244		// 7: the rejected selects moved no cursor; with i1 the only healthy
245		// instance it is chosen again, and the rejected replacement never changed
246		// the address to h2:9090.
247		if r := got.Results[7]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" {
248			t.Fatalf("result 7: %+v", r)
249		}
250		// Final snapshot: revision 1, i1 at its original address healthy at 1, i2
251		// still unknown at its original address.
252		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
253			t.Fatalf("services: %+v", got.Services)
254		}
255		insts := got.Services[0].Instances
256		if len(insts) != 2 {
257			t.Fatalf("instances: %+v", insts)
258		}
259		if insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 1 {
