263			t.Fatalf("i2 state: %+v", insts[1])
264		}
265	}
266	
267	// TestRegisterOutOfRangeFieldPrecedence locks where the range rejection sits
268	// relative to the other field checks.
269	//
270	// A value that parses as int64 (the reported 4294967297 and negatives) reaches
271	// the registry, so the long-standing field order applies on every
272	// architecture: service name and instance id are checked before the revision
273	// range, and an explicit null/non-string sessionKey is rejected in the handler
274	// before anything else. The 32-bit-only subtest adds that, on a 32-bit build,
275	// the out-of-range revision is judged before the remaining content fields and
276	// the revision conflict, since it is still a field check.
277	//
278	// A token that cannot even be carried as int64 (the huge value) fails at the
279	// handler's raw-token parse, the same tier that rejects float/string revision
280	// tokens; TestRegisterExpectedRevisionBeyondInt64 covers it.
281	func TestRegisterOutOfRangeFieldPrecedence(t *testing.T) {
282		const overflow32 = "4294967297" // parses as int64; exceeds int only on 32-bit
283	
284		// Earlier-checked fields win on every architecture (on 64-bit the value is
285		// in range, but the name/id checks still precede the revision comparison).
286		out, code := runRegisterWith(t, `{"requests":[
