294		}
295		got := decodeRegisterOutput(t, out)
296		want := []string{
297			"service name must not be empty",
298			"instance id must not be empty",
299			"service name must not be empty",
300			"sessionKey must be a string, not null",
301		}
302		for i, sub := range want {
