332		// content fields and the revision conflict, at the service's revision 1.
333		out, code = runRegisterWith(t, `{"requests":[
334			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"}]},
335			{"type":"register","service":"svc","expectedRevision":`+overflow32+`,"instances":[{"id":"","address":"h1:8080"}]},
336			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":`+overflow32+`,"sequence":0,"healthy":true},
337			{"type":"select","service":"svc","expectedRevision":`+overflow32+`},
338			{"type":"select","service":"missing","expectedRevision":`+overflow32+`}
