1209		}
1210		// 10-12: observations under the pre-clear revisions conflict even though
1211		// their sequences exceed the old accepted ones; each names the request and
1212		// current revisions and restores no eligibility.
1213		if r := got.Results[10]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1214			!hasRevisionPair(r, 1, 3) || r.Revision != 3 {
1215			t.Fatalf("result 10 stale-revision report: %+v", r)
1216		}
1217		if r := got.Results[11]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1218			!hasRevisionPair(r, 2, 3) || r.Revision != 3 {
1219			t.Fatalf("result 11 stale-revision report: %+v", r)
1220		}
1221		if r := got.Results[12]; r.OK || r.Error != "conflict" || r.Reason == "" ||
1222			!hasRevisionPair(r, 1, 3) || r.Revision != 3 {
1223			t.Fatalf("result 12 stale-revision report: %+v", r)
1224		}
1225		// 13: the conflicting reports healed nothing — still no_healthy, and this
1226		// failed selection must not move the cursor either.
1227		if r := got.Results[13]; r.OK || r.Error != "no_healthy" ||
1228			r.Revision != 3 || r.InstanceID != "" || r.Address != "" {
1229			t.Fatalf("result 13 still no_healthy: %+v", r)
1230		}
1231		// 14-16: at the current revision a sequence of 1 suffices (the reset
1232		// dropped the old sequences 11-13); health reports never bump the
1233		// registration revision, which stays 3.
1234		if r := got.Results[14]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1235			t.Fatalf("result 14: %+v", r)
1236		}
1237		if r := got.Results[15]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1238			t.Fatalf("result 15: %+v", r)
1239		}
1240		if r := got.Results[16]; !r.OK || !r.Changed || r.Revision != 3 || r.Sequence != 1 {
1241			t.Fatalf("result 16: %+v", r)
1242		}
1243		// 17: the cursor survived the empty list on b, so the rotation continues
1244		// just after b and returns c with its current address and new sequence.
1245		if r := got.Results[17]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 1 || r.Revision != 3 {
1246			t.Fatalf("result 17 should resume after b at c: %+v", r)
1247		}
1248		// 18: only now does the rotation wrap back to a.
1249		if r := got.Results[18]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 || r.Revision != 3 {
1250			t.Fatalf("result 18 should wrap to a: %+v", r)
1251		}
1252	
1253		// The final list keeps the service at revision 3 with the instances sorted
1254		// by id, all healthy at sequence 1 from the newly accepted observations;
1255		// c's pre-clear unhealthy reason is gone.
1256		if len(got.Services) != 1 {
1257			t.Fatalf("services: %+v", got.Services)
1258		}
1259		svc := got.Services[0]
1260		if svc.Service != "svc" || svc.Revision != 3 {
1261			t.Fatalf("service view: %+v", svc)
1262		}
1263		if len(svc.Instances) != 3 {
1264			t.Fatalf("instances: %+v", svc.Instances)
1265		}
1266		wantInsts := []registerInstance{
1267			{ID: "a", Address: "h1:1", Health: "healthy", Sequence: 1},
1268			{ID: "b", Address: "h2:2", Health: "healthy", Sequence: 1},
1269			{ID: "c", Address: "h3:3", Health: "healthy", Sequence: 1},
1270		}
1271		for i, want := range wantInsts {
1272			if svc.Instances[i] != want {
1273				t.Fatalf("instance %d: got %+v want %+v", i, svc.Instances[i], want)
1274			}
1275		}
1276	}
1277	
1278	// TestRejectedConflictReplacementKeepsRotationPosition isolates the rotation
1279	// guarantee at the batch level: the conflicting replacement is the very next
1280	// item after the first successful selection, so the following select must
1281	// continue at the next healthy id (i2). A failure path that reset the rotation
1282	// would select i1 again instead. The conflicting list is otherwise valid and
1283	// changes i1's address, which also must not take effect.
1284	func TestRejectedConflictReplacementKeepsRotationPosition(t *testing.T) {
1285		input := `{"requests":[
1286			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1287			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1288			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1289			{"type":"select","service":"svc","expectedRevision":1},
1290			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"hx:8080"},{"id":"i2","address":"h2:8080"}]},
1291			{"type":"select","service":"svc","expectedRevision":1}
1292		]}`
1293		out, code := runRegisterWith(t, input)
1294		if code != 1 {
1295			t.Fatalf("batch contains a failure, exit code: %d, output: %s", code, out)
1296		}
1297		var got registerOutput
1298		if err := json.Unmarshal([]byte(out), &got); err != nil {
1299			t.Fatalf("output is not JSON: %v\n%s", err, out)
1300		}
1301		if len(got.Results) != 6 {
1302			t.Fatalf("results: %+v", got.Results)
1303		}
1304		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 {
