1312		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1313			t.Fatalf("select after conflict must continue at i2 with its original state: %+v", r)
1314		}
1315		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
1316			t.Fatalf("services: %+v", got.Services)
1317		}
1318		if insts := got.Services[0].Instances; len(insts) != 2 ||
1319			insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 11 ||
1320			insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "healthy" || insts[1].Sequence != 22 {
1321			t.Fatalf("final list must keep only accepted state: %+v", insts)
1322		}
