1325	// TestRejectedInvalidReplacementKeepsRotationPosition is the invalid-content
1326	// counterpart: the malformed replacement follows the first successful
1327	// selection immediately, so the next select must still move to i2 rather than
1328	// repeating i1, and the valid prefix changing i1's address must not apply.
1329	func TestRejectedInvalidReplacementKeepsRotationPosition(t *testing.T) {
1330		input := `{"requests":[
1331			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"h1:8080"},{"id":"i2","address":"h2:8080"}]},
1332			{"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":11,"healthy":true},
1333			{"type":"health","service":"svc","instanceId":"i2","expectedRevision":1,"sequence":22,"healthy":true},
1334			{"type":"select","service":"svc","expectedRevision":1},
1335			{"type":"register","service":"svc","expectedRevision":7,"instances":[{"id":"i1","address":"h9:8080"},{"id":"i2","address":"bad-address"}]},
1336			{"type":"select","service":"svc","expectedRevision":1}
1337		]}`
1338		out, code := runRegisterWith(t, input)
1339		if code != 1 {
1340			t.Fatalf("batch contains a failure, exit code: %d, output: %s", code, out)
1341		}
1342		var got registerOutput
1343		if err := json.Unmarshal([]byte(out), &got); err != nil {
1344			t.Fatalf("output is not JSON: %v\n%s", err, out)
1345		}
1346		if len(got.Results) != 6 {
1347			t.Fatalf("results: %+v", got.Results)
1348		}
1349		if r := got.Results[3]; !r.OK || r.InstanceID != "i1" || r.Address != "h1:8080" || r.Sequence != 11 {
1350			t.Fatalf("first select: %+v", r)
1351		}
1352		// Wrong revision AND invalid content: invalid wins; the reason is the
1353		// address problem, with no expected/actual revision comparison reported.
1354		if r := got.Results[4]; r.OK || r.Error != "invalid" || r.Revision != 1 ||
1355			!omitsRevisionPair(r) {
1356			t.Fatalf("invalid replacement: %+v", r)
1357		}
1358		if !strings.Contains(got.Results[4].Reason, `instance address "bad-address" is not a host:port address`) {
1359			t.Fatalf("invalid reason should name the bad address, got %q", got.Results[4].Reason)
1360		}
1361		// i1's valid-prefix new address and any cursor reset must both be absent:
1362		// the rotation continues at i2 with its original address and sequence.
1363		if r := got.Results[5]; !r.OK || r.InstanceID != "i2" || r.Address != "h2:8080" || r.Sequence != 22 || r.Revision != 1 {
1364			t.Fatalf("select after invalid replacement must continue at i2 with its original state: %+v", r)
1365		}
1366		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
1367			t.Fatalf("services: %+v", got.Services)
1368		}
1369		if insts := got.Services[0].Instances; len(insts) != 2 ||
1370			insts[0].ID != "i1" || insts[0].Address != "h1:8080" || insts[0].Health != "healthy" || insts[0].Sequence != 11 ||
1371			insts[1].ID != "i2" || insts[1].Address != "h2:8080" || insts[1].Health != "healthy" || insts[1].Sequence != 22 {
1372			t.Fatalf("final list must keep only accepted state: %+v", insts)
1373		}
1374	}
1375	
1376	// TestSelectSessionKeySticky covers the session flow end to end: the first
1377	// request with a key rotates and binds, later requests with the same trimmed
1378	// key reuse the bound instance without moving the rotation, and plain selects
1379	// interleaved between them keep rotating from the last rotated position.
1380	func TestSelectSessionKeySticky(t *testing.T) {
1381		input := `{"requests":[
1382			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"}]},
1383			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":1,"healthy":true},
1384			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":2,"healthy":true},
1385			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":3,"healthy":true},
1386			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1387			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"s1"},
1388			{"type":"select","service":"svc","expectedRevision":1},
1389			{"type":"select","service":"svc","expectedRevision":1,"sessionKey":"  s1  "},
1390			{"type":"select","service":"svc","expectedRevision":1}
1391		]}`
1392		out, code := runRegisterWith(t, input)
1393		if code != 0 {
1394			t.Fatalf("exit code: %d, output: %s", code, out)
1395		}
1396		var got registerOutput
1397		if err := json.Unmarshal([]byte(out), &got); err != nil {
1398			t.Fatalf("output is not JSON: %v\n%s", err, out)
1399		}
1400		if len(got.Results) != 9 {
1401			t.Fatalf("results: %+v", got.Results)
1402		}
1403		// 4: first use of the key rotates to the smallest id and binds s1 -> a.
1404		if r := got.Results[4]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 1 {
1405			t.Fatalf("first session select: %+v", r)
1406		}
1407		// 5: reuse returns a again without advancing the rotation.
1408		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Sequence != 1 {
1409			t.Fatalf("session reuse: %+v", r)
1410		}
1411		// 6: a plain select continues just after a, proving the reuse did not
1412		// move the cursor.
1413		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Sequence != 2 {
1414			t.Fatalf("plain select after reuse: %+v", r)
1415		}
1416		// 7: the padded key trims to the same session and still reuses a.
1417		if r := got.Results[7]; !r.OK || r.InstanceID != "a" {
1418			t.Fatalf("padded key should reuse the same session: %+v", r)
1419		}
1420		// 8: the next plain select continues after b.
1421		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Sequence != 3 {
1422			t.Fatalf("plain select should continue after b: %+v", r)
